import { test, expect } from '@playwright/test';

test.describe('Mobile Navigation Hamburger Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.setViewportSize({ width: 375, height: 667 });
  });

  test('should display hamburger menu button on mobile viewport', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });
    await expect(hamburgerButton).toBeVisible();
  });

  test('should hide navigation menu by default on mobile', async ({ page }) => {
    const navigationMenu = page.getByRole('navigation');
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });

    await expect(hamburgerButton).toBeVisible();

    const menuItems = page.getByRole('link', { name: /home|about|services|contact|products/i });
    const firstMenuItem = menuItems.first();

    const isMenuVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isMenuVisible).toBe(false);
  });

  test('should toggle navigation menu when hamburger button is clicked', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });
    const navigationMenu = page.getByRole('navigation');

    await expect(hamburgerButton).toBeVisible();

    const menuItems = page.getByRole('link', { name: /home|about|services|contact|products/i });
    const firstMenuItem = menuItems.first();

    let isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(false);

    await hamburgerButton.click();

    isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(true);

    await hamburgerButton.click();

    isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(false);
  });

  test('should close menu when a navigation link is clicked', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });
    const homeLink = page.getByRole('link', { name: /home/i }).first();

    await hamburgerButton.click();

    let isVisible = await homeLink.isVisible().catch(() => false);
    expect(isVisible).toBe(true);

    await homeLink.click();

    isVisible = await homeLink.isVisible().catch(() => false);
    expect(isVisible).toBe(false);
  });

  test('should display hamburger menu icon with correct aria attributes', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });

    await expect(hamburgerButton).toBeVisible();

    const ariaExpanded = await hamburgerButton.getAttribute('aria-expanded');
    expect(['true', 'false']).toContain(ariaExpanded);

    const ariaLabel = await hamburgerButton.getAttribute('aria-label');
    expect(ariaLabel).toBeTruthy();
  });

  test('should update aria-expanded attribute when menu is toggled', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });

    let ariaExpanded = await hamburgerButton.getAttribute('aria-expanded');
    expect(ariaExpanded).toBe('false');

    await hamburgerButton.click();

    ariaExpanded = await hamburgerButton.getAttribute('aria-expanded');
    expect(ariaExpanded).toBe('true');

    await hamburgerButton.click();

    ariaExpanded = await hamburgerButton.getAttribute('aria-expanded');
    expect(ariaExpanded).toBe('false');
  });

  test('should not display hamburger menu on desktop viewport', async ({ page }) => {
    await page.setViewportSize({ width: 1920, height: 1080 });

    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });
    const isVisible = await hamburgerButton.isVisible().catch(() => false);

    expect(isVisible).toBe(false);

    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();

    const menuItems = page.getByRole('link', { name: /home|about|services|contact|products/i });
    const firstMenuItem = menuItems.first();
    await expect(firstMenuItem).toBeVisible();
  });

  test('should handle rapid menu toggle clicks', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });
    const menuItems = page.getByRole('link', { name: /home|about|services|contact|products/i });
    const firstMenuItem = menuItems.first();

    await hamburgerButton.click();
    await hamburgerButton.click();
    await hamburgerButton.click();

    let isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(true);

    await hamburgerButton.click();

    isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(false);
  });

  test('should maintain menu state during page interactions', async ({ page }) => {
    const hamburgerButton = page.getByRole('button', { name: /menu|hamburger|toggle navigation/i });
    const menuItems = page.getByRole('link', { name: /home|about|services|contact|products/i });
    const firstMenuItem = menuItems.first();

    await hamburgerButton.click();

    let isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(true);

    await page.waitForTimeout(500);

    isVisible = await firstMenuItem.isVisible().catch(() => false);
    expect(isVisible).toBe(true);
  });
});
